// MARK: - Block union

/// Any block in a fired `:json` artifact, told apart by `_type`.
public indirect enum Block: Codable, Hashable, Sendable {
    case accordion(AccordionBlock)
    case audio(AudioBlock)
    case claim(ClaimBlock)
    case columns(ColumnsBlock)
    case custom(CustomBlock)
    case divider(DividerBlock)
    case embed(EmbedBlock)
    case faq(FaqBlock)
    case file(FileBlock)
    case form(FormBlock)
    case fragment(FragmentBlock)
    case gallery(GalleryBlock)
    case heading(HeadingBlock)
    case howTo(HowToBlock)
    case image(ImageBlock)
    case newsletterSignup(NewsletterSignupBlock)
    case quote(QuoteBlock)
    case richText(RichTextBlock)
    case video(VideoBlock)
    /// A block type this build does not know — one added after it was generated.
    case unknown(type: String)

    private enum TagKey: String, CodingKey {
        case tag = "_type"
    }

    public var type: String {
        switch self {
        case .accordion: return "accordion"
        case .audio: return "audio"
        case .claim: return "claim"
        case .columns: return "columns"
        case .custom: return "custom"
        case .divider: return "divider"
        case .embed: return "embed"
        case .faq: return "faq"
        case .file: return "file"
        case .form: return "form"
        case .fragment: return "fragment"
        case .gallery: return "gallery"
        case .heading: return "heading"
        case .howTo: return "how_to"
        case .image: return "image"
        case .newsletterSignup: return "newsletter_signup"
        case .quote: return "quote"
        case .richText: return "rich_text"
        case .video: return "video"
        case .unknown(let type): return type
        }
    }

    public init(from decoder: Decoder) throws {
        let type = try decoder.container(keyedBy: TagKey.self).decode(String.self, forKey: .tag)
        switch type {
        case "accordion": self = .accordion(try AccordionBlock(from: decoder))
        case "audio": self = .audio(try AudioBlock(from: decoder))
        case "claim": self = .claim(try ClaimBlock(from: decoder))
        case "columns": self = .columns(try ColumnsBlock(from: decoder))
        case "custom": self = .custom(try CustomBlock(from: decoder))
        case "divider": self = .divider(try DividerBlock(from: decoder))
        case "embed": self = .embed(try EmbedBlock(from: decoder))
        case "faq": self = .faq(try FaqBlock(from: decoder))
        case "file": self = .file(try FileBlock(from: decoder))
        case "form": self = .form(try FormBlock(from: decoder))
        case "fragment": self = .fragment(try FragmentBlock(from: decoder))
        case "gallery": self = .gallery(try GalleryBlock(from: decoder))
        case "heading": self = .heading(try HeadingBlock(from: decoder))
        case "how_to": self = .howTo(try HowToBlock(from: decoder))
        case "image": self = .image(try ImageBlock(from: decoder))
        case "newsletter_signup": self = .newsletterSignup(try NewsletterSignupBlock(from: decoder))
        case "quote": self = .quote(try QuoteBlock(from: decoder))
        case "rich_text": self = .richText(try RichTextBlock(from: decoder))
        case "video": self = .video(try VideoBlock(from: decoder))
        default: self = .unknown(type: type)
        }
    }

    public func encode(to encoder: Encoder) throws {
        switch self {
        case .accordion(let value): try value.encode(to: encoder)
        case .audio(let value): try value.encode(to: encoder)
        case .claim(let value): try value.encode(to: encoder)
        case .columns(let value): try value.encode(to: encoder)
        case .custom(let value): try value.encode(to: encoder)
        case .divider(let value): try value.encode(to: encoder)
        case .embed(let value): try value.encode(to: encoder)
        case .faq(let value): try value.encode(to: encoder)
        case .file(let value): try value.encode(to: encoder)
        case .form(let value): try value.encode(to: encoder)
        case .fragment(let value): try value.encode(to: encoder)
        case .gallery(let value): try value.encode(to: encoder)
        case .heading(let value): try value.encode(to: encoder)
        case .howTo(let value): try value.encode(to: encoder)
        case .image(let value): try value.encode(to: encoder)
        case .newsletterSignup(let value): try value.encode(to: encoder)
        case .quote(let value): try value.encode(to: encoder)
        case .richText(let value): try value.encode(to: encoder)
        case .video(let value): try value.encode(to: encoder)
        case .unknown(let type):
            var container = encoder.container(keyedBy: TagKey.self)
            try container.encode(type, forKey: .tag)
        }
    }
}


// MARK: - Documents

/// A published `Recipe` as fired to the `:json` surface.
public struct RecipeDocument: Codable, Hashable, Sendable {
    public let blocks: [Block]
    /// Admin-defined custom fields (`KilnCMS.CMS.FieldDefinition`). Open: a point-in-time read (`?as_of=`) serves the values stored at that instant, which may include fields since removed from the registry.
    public let customFields: CustomFields
    /// Plain-text renditions of the `:text` custom fields marked `deliver_plain`: the stored value with its HTML tags removed, entities decoded and whitespace collapsed (to one line, unless the field keeps its breaks). `null` where the record holds no value.
    public let customFieldsPlain: CustomFieldsPlain?
    /// Portable Text renditions of the rich `:text` custom fields marked `deliver_portable`: the stored HTML as the same block tree a `rich_text` block's `body` holds. `null` where the record holds no value.
    public let customFieldsPortable: CustomFieldsPortable?
    public let id: String
    public let locale: String?
    public let slug: String?
    public let title: String?
    public let type: String

    public init(blocks: [Block], customFields: CustomFields, customFieldsPlain: CustomFieldsPlain? = nil, customFieldsPortable: CustomFieldsPortable? = nil, id: String, locale: String? = nil, slug: String? = nil, title: String? = nil, type: String) {
        self.blocks = blocks
        self.customFields = customFields
        self.customFieldsPlain = customFieldsPlain
        self.customFieldsPortable = customFieldsPortable
        self.id = id
        self.locale = locale
        self.slug = slug
        self.title = title
        self.type = type
    }

    enum CodingKeys: String, CodingKey {
        case blocks
        case customFields = "custom_fields"
        case customFieldsPlain = "custom_fields_plain"
        case customFieldsPortable = "custom_fields_portable"
        case id
        case locale
        case slug
        case title
        case type
    }

    public struct CustomFields: Codable, Hashable, Sendable {
        /// Snapshot of the picked media item.
        public let hero: MediaSnapshot?
        /// Rows of this group, in the order the editor arranged them.
        public let ingredients: [IngredientsItem]?
        public let method: String?
        public let minutes: Int?
        public let serves: Int?

        public init(hero: MediaSnapshot? = nil, ingredients: [IngredientsItem]? = nil, method: String? = nil, minutes: Int? = nil, serves: Int? = nil) {
            self.hero = hero
            self.ingredients = ingredients
            self.method = method
            self.minutes = minutes
            self.serves = serves
        }

        public struct IngredientsItem: Codable, Hashable, Sendable {
            public let amount: Double?
            public let item: String?
            public let unit: String?

            public init(amount: Double? = nil, item: String? = nil, unit: String? = nil) {
                self.amount = amount
                self.item = item
                self.unit = unit
            }
        }
    }

    public struct CustomFieldsPlain: Codable, Hashable, Sendable {
        /// Keeps the value's breaks: a blank line between paragraphs, a newline per line break and list item.
        public let method: String?

        public init(method: String? = nil) {
            self.method = method
        }
    }

    public struct CustomFieldsPortable: Codable, Hashable, Sendable {
        /// Portable Text — the canonical rich-text representation (D12).
        public let method: [PortableTextBlock]?

        public init(method: [PortableTextBlock]? = nil) {
            self.method = method
        }
    }
}


// MARK: - Document union

/// Any content in a fired `:json` artifact, told apart by `type`.
public indirect enum Document: Codable, Hashable, Sendable {
    case recipe(RecipeDocument)
    /// A content type this build does not know — one added after it was generated.
    case unknown(type: String)

    private enum TagKey: String, CodingKey {
        case tag = "type"
    }

    public var type: String {
        switch self {
        case .recipe: return "recipe"
        case .unknown(let type): return type
        }
    }

    public init(from decoder: Decoder) throws {
        let type = try decoder.container(keyedBy: TagKey.self).decode(String.self, forKey: .tag)
        switch type {
        case "recipe": self = .recipe(try RecipeDocument(from: decoder))
        default: self = .unknown(type: type)
        }
    }

    public func encode(to encoder: Encoder) throws {
        switch self {
        case .recipe(let value): try value.encode(to: encoder)
        case .unknown(let type):
            var container = encoder.container(keyedBy: TagKey.self)
            try container.encode(type, forKey: .tag)
        }
    }
}


// MARK: - JSONValue

/// Any JSON value — what an open map, an unconstrained field or a union
/// Swift cannot name decodes to.
public indirect enum JSONValue: Codable, Hashable, Sendable {
    case null
    case bool(Bool)
    case number(Double)
    case string(String)
    case array([JSONValue])
    case object([String: JSONValue])

    public init(from decoder: Decoder) throws {
        let container = try decoder.singleValueContainer()
        if container.decodeNil() {
            self = .null
        } else if let value = try? container.decode(Bool.self) {
            self = .bool(value)
        } else if let value = try? container.decode(Double.self) {
            self = .number(value)
        } else if let value = try? container.decode(String.self) {
            self = .string(value)
        } else if let value = try? container.decode([JSONValue].self) {
            self = .array(value)
        } else {
            self = .object(try container.decode([String: JSONValue].self))
        }
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.singleValueContainer()
        switch self {
        case .null: try container.encodeNil()
        case .bool(let value): try container.encode(value)
        case .number(let value): try container.encode(value)
        case .string(let value): try container.encode(value)
        case .array(let value): try container.encode(value)
        case .object(let value): try container.encode(value)
        }
    }
}
